import java.util.*;
import java.io.*;

public class Main {
    static class Hungarian {
        public static final int SIZE = 2000;
        int cnt;
        int[] pos = new int[SIZE];
        int[] rev = new int[SIZE];
        int[] v = new int[SIZE];

        public int gao(int n, List<Integer>[] e) {
            cnt = 0;
            Arrays.fill(pos, -1);
            Arrays.fill(rev, -1);
            for (int i = 0; i < n; i++) {
                Arrays.fill(v, 0);
                if (match(i, e)) cnt++;
            }
            return cnt;
        }

        private boolean match(int x, List<Integer>[] e) {
            for (int y : e[x]) {
                if (v[y] == 0) {
                    v[y] = 1;
                    if (rev[y] < 0 || match(rev[y], e)) {
                        pos[x] = y;
                        rev[y] = x;
                        return true;
                    }
                }
            }
            return false;
        }
    }

    static final int INF = 1000000000;
    static final int[] dr = {0, -1, 0, 1};
    static final int[] dc = {1, 0, -1, 0};
    static int[][] a = new int[12][12];
    static int[][] b = new int[12][12];
    static int[][] f = new int[12][12];
    static int n, t;
    static List<Integer>[] e = new ArrayList[2000];
    static List<Integer>[][] c = new ArrayList[12][12];

    static {
        for (int i = 0; i < 2000; i++) {
            e[i] = new ArrayList<>();
        }
        for (int i = 0; i < 12; i++) {
            for (int j = 0; j < 12; j++) {
                c[i][j] = new ArrayList<>();
            }
        }
    }

    static void floodfill(int sr, int sc) {
        int[][] dist = new int[12][12];
        for (int[] row : dist) Arrays.fill(row, -1);
        Queue<Integer> qr = new LinkedList<>();
        Queue<Integer> qc = new LinkedList<>();
        qr.offer(sr);
        qc.offer(sc);
        dist[sr][sc] = 0;
        while (!qr.isEmpty()) {
            int r = qr.poll();
            int c_ = qc.poll();
            for (int i = 0; i < 4; i++) {
                int tr = r + dr[i];
                int tc = c_ + dc[i];
                if (tr >= 0 && tr < n && tc >= 0 && tc < n && a[tr][tc] >= 0 && dist[tr][tc] < 0) {
                    dist[tr][tc] = dist[r][c_] + 1;
                    qr.offer(tr);
                    qc.offer(tc);
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                f[i][j] = dist[i][j];
            }
        }
    }

    static void setmark(int sr, int sc, int cnt) {
        int[][] v = new int[12][12];
        for (int[] row : v) Arrays.fill(row, -1);
        Queue<Integer> qr = new LinkedList<>();
        Queue<Integer> qc = new LinkedList<>();
        qr.offer(sr);
        qc.offer(sc);
        v[sr][sc] = 0;
        while (!qr.isEmpty()) {
            int r = qr.poll();
            int c_ = qc.poll();
            if (v[r][c_] > Math.min(t, f[r][c_])) continue;
            for (int j : c[r][c_]) {
                for (int i = 0; i < cnt; i++) {
                    e[n + i].add(j);
                }
            }
            if (v[r][c_] == Math.min(t, f[r][c_])) continue;
            for (int i = 0; i < 4; i++) {
                int tr = r + dr[i];
                int tc = c_ + dc[i];
                if (tr >= 0 && tr < n && tc >= 0 && tc < n && a[tr][tc] >= 0 && v[tr][tc] < 0) {
                    v[tr][tc] = v[r][c_] + 1;
                    qr.offer(tr);
                    qc.offer(tc);
                }
            }
        }
        n += cnt;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int m = 0, o = 0, sr = -1, sc = -1;
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());
        for (int[] row : a) Arrays.fill(row, -1);
        for (int[] row : b) Arrays.fill(row, -1);
        for (int i = 0; i < 12; i++) {
            for (int j = 0; j < 12; j++) {
                c[i][j].clear();
            }
        }
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            for (int j = 0; j < n; j++) {
                char ch = line.charAt(j);
                if (ch >= '0' && ch <= '9') {
                    a[i][j] = ch - '0';
                }
                if (ch == 'Z') {
                    sr = i;
                    sc = j;
                }
            }
        }
        floodfill(sr, sc);
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            for (int j = 0; j < n; j++) {
                char ch = line.charAt(j);
                if (ch >= '0' && ch <= '9') {
                    b[i][j] = ch - '0';
                }
                for (int k = 0; k < b[i][j]; k++) {
                    c[i][j].add(o++);
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (f[i][j] < 0) f[i][j] = INF;
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (a[i][j] > 0) setmark(i, j, a[i][j]);
            }
        }
        Hungarian match = new Hungarian();
        System.out.println(match.gao(m, e));
    }
</main>
